/* Affichage Belgique sans doublons linguistiques - 2026-09-04 */
(function(){
  var aliases={
    'sint-truiden':'Saint-Trond','saint-trond':'Saint-Trond','st-trond':'Saint-Trond','st trond':'Saint-Trond',
    'leuven':'Louvain','antwerpen':'Anvers','gent':'Gand','brugge':'Bruges','kortrijk':'Courtrai',
    'mechelen':'Malines','tienen':'Tirlemont','ronse':'Renaix','sint-niklaas':'Saint-Nicolas',
    'tongeren':'Tongres','doornik':'Tournai','bergen':'Mons','luik':'Liège','namen':'Namur'
  };
  function n(v){return String(v||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim()}
  function displayCity(v){var x=n(v); for(var k in aliases){if(x===n(k)||x.indexOf(n(k)+' ')===0)return aliases[k]} return v}
  function placeKey(v){return n(v).replace(/\b(marche|markt|hebdomadaire|wekelijkse|de|du|la|le|het|weekly|zaterdagmarkt|haspengouwmarkt)\b/g,' ').replace(/\s+/g,' ').trim()}
  var seen={},out=[],i,r,city,key;
  for(i=0;i<data.length;i++){
    r=data[i]; if(!r)continue;
    city=displayCity(r[3]||'');
    /* Saint-Trond : une seule fiche Haspengouw le samedi, mais Sunday Markt reste distinct */
    if(n(r[3]).indexOf('sint truiden')===0 && n(r[4])==='samedi' && (n(r[2]).indexOf('haspengouw')>=0||n(r[2]).indexOf('marche de sint truiden')>=0)){
      city='Saint-Trond'; r[2]='Haspengouw Markt'; r[3]=city;
    } else if(city!==r[3]) r[3]=city;
    if(n(city)==='saint trond' && n(r[4])==='samedi' && n(r[2]).indexOf('haspengouw')>=0){
      key='limbourg|saint trond|samedi|haspengouw';
    } else {
      key=n(r[0])+'|'+n(city)+'|'+n(r[4])+'|'+placeKey(r[8]||r[2]);
    }
    if(seen[key])continue;
    seen[key]=1;out.push(r);
  }
  data=out;
  window.BE_CITY_ALIASES=aliases;
})();


/* Nettoyage final Belgique : noms français + suppression des doublons locaux - 2026-09-05 */
(function(){
  var cityFr={
    'sint-truiden':'Saint-Trond','leuven':'Louvain','antwerpen':'Anvers','gent':'Gand','brugge':'Bruges',
    'kortrijk':'Courtrai','mechelen':'Malines','tienen':'Tirlemont','ronse':'Renaix','sint-niklaas':'Saint-Nicolas',
    'tongeren':'Tongres','doornik':'Tournai','bergen':'Mons','luik':'Liège','namen':'Namur','aalst':'Alost',
    'oudenaarde':'Audenarde','geraardsbergen':'Grammont','ieper':'Ypres','roeselare':'Roulers','dendermonde':'Termonde',
    'diksmuide':'Dixmude','oostende':'Ostende','veurne':'Furnes','menen':'Menin'
  };
  function n(v){return String(v||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim()}
  function frCity(v){var x=n(v),k;for(k in cityFr){if(x===n(k))return cityFr[k]}return v}
  function cleanTitle(t){
    var x=String(t||''),pairs=[
      [/\bSint[- ]Truiden\b/gi,'Saint-Trond'],[/\bLeuven\b/gi,'Louvain'],[/\bAntwerpen\b/gi,'Anvers'],[/\bGent\b/gi,'Gand'],
      [/\bBrugge\b/gi,'Bruges'],[/\bKortrijk\b/gi,'Courtrai'],[/\bMechelen\b/gi,'Malines'],[/\bTienen\b/gi,'Tirlemont'],
      [/\bRonse\b/gi,'Renaix'],[/\bSint[- ]Niklaas\b/gi,'Saint-Nicolas'],[/\bTongeren\b/gi,'Tongres'],[/\bAalst\b/gi,'Alost'],
      [/\bOudenaarde\b/gi,'Audenarde'],[/\bGeraardsbergen\b/gi,'Grammont'],[/\bIeper\b/gi,'Ypres'],[/\bRoeselare\b/gi,'Roulers'],
      [/\bDendermonde\b/gi,'Termonde'],[/\bDiksmuide\b/gi,'Dixmude'],[/\bOostende\b/gi,'Ostende'],[/\bVeurne\b/gi,'Furnes'],[/\bMenen\b/gi,'Menin']
    ];
    pairs.forEach(function(p){x=x.replace(p[0],p[1])});return x;
  }
  function locKey(v){
    var x=n(v).replace(/\b\d{4}\b/g,' '),k;
    for(k in cityFr){x=x.replace(new RegExp('\\b'+n(k).replace(/ /g,'\\s+')+'\\b','g'),' '+n(cityFr[k])+' ')}
    return x.replace(/\s+/g,' ').trim();
  }
  function score(r){
    var s=0;
    if(typeof r[9]==='number'&&typeof r[10]==='number')s+=8;
    if(Array.isArray(r[9])&&r[9].length)s+=2;
    if(Array.isArray(r[10])&&r[10].length)s+=2;
    if(r[5]&&!/verifier|non publie|horaire/i.test(n(r[5])))s+=3;
    if(r[6]&&!/non publie|verifier/i.test(n(r[6])))s+=2;
    if(r[7]&&!/non publie|verifier/i.test(n(r[7])))s+=1;
    if(r[8]&&String(r[8]).length>12)s+=2;
    if(r[2]&&String(r[2]).length>12)s+=1;
    return s;
  }
  var best={},order=[],i,r,key,city;
  for(i=0;i<data.length;i++){
    r=data[i];if(!r)continue;
    city=frCity(r[3]);r[3]=city;r[2]=cleanTitle(r[2]);
    key=n(r[0])+'|'+n(city)+'|'+n(r[4])+'|'+locKey(r[8]||'');
    if(!best[key]){best[key]=r;order.push(key)}
    else if(score(r)>score(best[key]))best[key]=r;
  }
  data=order.map(function(k){return best[k]});
  window.BE_CITY_ALIASES=Object.assign({},window.BE_CITY_ALIASES||{},cityFr);
})();


/* Fusion renforcée des doublons de sources (même marché, nom local/français) - 2026-09-05 */
(function(){
  function n(v){return String(v||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim()}
  function titleKey(v,city){
    var x=n(v),c=n(city);
    x=x.replace(new RegExp('\\b'+c.replace(/ /g,'\\s+')+'\\b','g'),' ')
      .replace(/\b(marche|markt|hebdomadaire|wekelijkse|weekly|du|de|la|le|centre|centrum|zaterdagmarkt|vrijdagmarkt|maandagmarkt|dinsdagmarkt|woensdagmarkt|donderdagmarkt|zondagmarkt)\b/g,' ')
      .replace(/\s+/g,' ').trim();
    return x;
  }
  function locTokens(v,city){
    var x=n(v),c=n(city),stop={belgique:1,belgie:1,flandre:1,limbourg:1,province:1,centre:1,centrum:1,ville:1};
    x=x.replace(/\b\d{4}\b/g,' ').replace(new RegExp('\\b'+c.replace(/ /g,'\\s+')+'\\b','g'),' ');
    return x.split(/\s+/).filter(function(t){return t&&t.length>2&&!stop[t]&&!/^\d+$/.test(t)});
  }
  function overlap(a,b){
    var A={},B={},i,inter=0;for(i=0;i<a.length;i++)A[a[i]]=1;for(i=0;i<b.length;i++)B[b[i]]=1;
    var ka=Object.keys(A),kb=Object.keys(B);if(!ka.length||!kb.length)return 0;
    ka.forEach(function(k){if(B[k])inter++});return inter/Math.min(ka.length,kb.length);
  }
  function score(r){
    var s=0,v;
    if(typeof r[9]==='number'&&typeof r[10]==='number')s+=10;
    v=n(r[5]);if(v&&!/verifier|non publie|horaire/.test(v))s+=4;
    v=n(r[6]);if(v&&!/verifier|non publie/.test(v))s+=3;
    v=n(r[7]);if(v&&!/verifier|non publie/.test(v))s+=2;
    if(Array.isArray(r[9])&&r[9].length)s+=2;
    if(r[8]&&String(r[8]).length>15)s+=2;
    if(r[2]&&String(r[2]).length>15)s+=1;
    return s;
  }
  /* Evite le libellé "Saint-Trond / Saint-Trond" créé par les anciennes corrections. */
  data.forEach(function(r){if(r&&n(r[3])==='saint trond'&&/haspengouw/i.test(String(r[2]||'')))r[2]='Haspengouw Markt'});
  var out=[];
  data.forEach(function(r){
    if(!r)return;
    var city=r[3],day=n(r[4]),tk=titleKey(r[2],city),lt=locTokens(r[8],city),found=-1;
    for(var i=0;i<out.length;i++){
      var q=out[i];if(n(q[3])!==n(city)||n(q[4])!==day)continue;
      var qtk=titleKey(q[2],q[3]),qlt=locTokens(q[8],q[3]);
      var sameTitle=(tk&&qtk&&tk===qtk)||n(r[2])===n(q[2]);
      var locMatch=overlap(lt,qlt);
      var genericA=/^marche de\b/.test(n(r[2])),genericB=/^marche de\b/.test(n(q[2]));
      if(sameTitle || ((genericA||genericB) && locMatch>=0.80 && Math.min(lt.length,qlt.length)>=2)) {found=i;break}
    }
    if(found<0)out.push(r); else if(score(r)>score(out[found]))out[found]=r;
  });
  data=out;
})();
